-- Migración: módulo de Rutas de Vibración
-- Ejecutar en SQL Editor de Supabase.

CREATE TABLE IF NOT EXISTS rutas_vibracion (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  nombre TEXT NOT NULL UNIQUE,
  unidad TEXT NOT NULL,
  frecuencia TEXT NOT NULL,
  nro_plan TEXT,
  activa BOOLEAN DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS ruta_equipos (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  ruta_id UUID REFERENCES rutas_vibracion(id) ON DELETE CASCADE,
  nombre TEXT NOT NULL,
  ubicacion_tecnica TEXT,
  unidad TEXT,
  equipo_id UUID,
  orden INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(ruta_id, nombre)
);

CREATE TABLE IF NOT EXISTS ruta_ejecuciones (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  ruta_id UUID REFERENCES rutas_vibracion(id),
  orden_trabajo TEXT,
  fecha_inicio DATE DEFAULT CURRENT_DATE,
  fecha_cierre DATE,
  estado TEXT DEFAULT 'en_progreso',
  created_by UUID,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS ruta_ejecucion_equipos (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  ejecucion_id UUID REFERENCES ruta_ejecuciones(id) ON DELETE CASCADE,
  ruta_equipo_id UUID REFERENCES ruta_equipos(id),
  completado BOOLEAN DEFAULT false,
  observacion TEXT,
  completado_at TIMESTAMPTZ,
  completado_by UUID,
  UNIQUE(ejecucion_id, ruta_equipo_id)
);

